#!/usr/bin/env node
const { spawn } = require('child_process');

const argv = process.argv.slice(2);
if (argv.length === 0) {
  console.error('Usage: node mcp_stdio_probe.js <command> [args...]');
  process.exit(2);
}

const child = spawn(argv[0], argv.slice(1), { stdio: ['pipe', 'pipe', 'pipe'] });
let stdoutBuf = Buffer.alloc(0);
let stderrBuf = '';
let nextId = 1;
const pending = new Map();
let initialized = false;

const timeoutMs = 12000;
const hardTimeout = setTimeout(() => {
  finish(1, 'FAIL timeout waiting for MCP responses');
}, timeoutMs);

child.stderr.on('data', (d) => {
  stderrBuf += d.toString('utf8');
});

function send(msg) {
  const body = Buffer.from(JSON.stringify(msg), 'utf8');
  const header = Buffer.from(`Content-Length: ${body.length}\r\n\r\n`, 'utf8');
  child.stdin.write(Buffer.concat([header, body]));
}

function request(method, params) {
  return new Promise((resolve, reject) => {
    const id = nextId++;
    pending.set(id, { resolve, reject, method });
    send({ jsonrpc: '2.0', id, method, params });
  });
}

function parseMessages() {
  while (true) {
    const sep = stdoutBuf.indexOf('\r\n\r\n');
    if (sep === -1) return;

    const header = stdoutBuf.slice(0, sep).toString('utf8');
    const m = header.match(/Content-Length:\s*(\d+)/i);
    if (!m) {
      stdoutBuf = stdoutBuf.slice(sep + 4);
      continue;
    }
    const len = Number(m[1]);
    const total = sep + 4 + len;
    if (stdoutBuf.length < total) return;

    const bodyBuf = stdoutBuf.slice(sep + 4, total);
    stdoutBuf = stdoutBuf.slice(total);

    let msg;
    try {
      msg = JSON.parse(bodyBuf.toString('utf8'));
    } catch {
      continue;
    }

    if (msg && typeof msg.id === 'number' && pending.has(msg.id)) {
      const p = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) p.reject(new Error(`${p.method} error: ${JSON.stringify(msg.error)}`));
      else p.resolve(msg.result);
    }
  }
}

child.stdout.on('data', (d) => {
  stdoutBuf = Buffer.concat([stdoutBuf, d]);
  parseMessages();
});

child.on('error', (err) => {
  finish(1, `FAIL spawn error: ${err.message}`);
});

child.on('exit', (code, signal) => {
  if (!initialized) {
    const details = stderrBuf.trim() ? ` stderr=${JSON.stringify(stderrBuf.trim().slice(0, 500))}` : '';
    finish(1, `FAIL server exited early code=${code} signal=${signal}${details}`);
  }
});

function finish(code, msg) {
  clearTimeout(hardTimeout);
  try { child.kill('SIGTERM'); } catch {}
  if (msg) {
    console.log(msg);
    if (stderrBuf.trim()) console.log(`STDERR: ${stderrBuf.trim().slice(0, 500)}`);
  }
  process.exit(code);
}

(async () => {
  try {
    const initResult = await request('initialize', {
      protocolVersion: '2024-11-05',
      capabilities: {},
      clientInfo: { name: 'mcp-probe', version: '1.0.0' }
    });
    initialized = true;

    send({ jsonrpc: '2.0', method: 'notifications/initialized', params: {} });

    let toolsCount = 0;
    let resourcesCount = -1;

    try {
      const tools = await request('tools/list', {});
      toolsCount = Array.isArray(tools?.tools) ? tools.tools.length : 0;
    } catch (e) {
      // Some servers may not expose tools; continue to resources
    }

    try {
      const resources = await request('resources/list', {});
      resourcesCount = Array.isArray(resources?.resources) ? resources.resources.length : 0;
    } catch {
      // optional
    }

    const serverName = initResult?.serverInfo?.name || 'unknown';
    const serverVersion = initResult?.serverInfo?.version || 'unknown';
    finish(0, `PASS ${serverName}@${serverVersion} tools=${toolsCount} resources=${resourcesCount}`);
  } catch (err) {
    finish(1, `FAIL ${err.message}`);
  }
})();
